DHT22 sensor calibration is a process of adjusting the sensor's readings to match the actual temperature and humidity conditions in your environment. The calibration process involves subtracting a offset value from the sensor's raw readings to get an accurate reading.

Here is an example code in Arduino language to calibrate a DHT22 sensor:
```c
#include <DHT.h>

#define DHT_PIN 2  // Pin number to connect DHT22 sensor

DHT dht(DHT_PIN, DHT22);

float calibrationOffsetTemperature = 0.0; // Initialize temperature offset
float calibrationOffsetHumidity = 0.0; // Initialize humidity offset

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  int temperature = dht.readTemperature(); // Read temperature from DHT22 sensor
  int humidity = dht.readHumidity(); // Read humidity from DHT22 sensor

  // Calculate the absolute difference between the sensor's reading and the actual temperature/humidity
  float tempDiff = abs(temperature - 25.0); // Replace 25.0 with the actual temperature
  float humDiff = abs(humidity - 50.0); // Replace 50.0 with the actual humidity

  // Update the calibration offset values
  calibrationOffsetTemperature += tempDiff / 100.0; // Divide by 100.0 to scale the offset
  calibrationOffsetHumidity += humDiff / 100.0; // Divide by 100.0 to scale the offset

  delay(1000); // Wait for 1 second before taking the next reading
}

void printCalibrationOffsets() {
  Serial.println("Calibration Offsets:");
  Serial.print("Temperature Offset: ");
  Serial.print(calibrationOffsetTemperature);
  Serial.println("°C");
  Serial.print("Humidity Offset: ");
  Serial.print(calibrationOffsetHumidity);
  Serial.println("%");
}

